CREATE TABLE [dbo].[ccPermissions](	  [Permissions_Id] INT NOT NULL	, [Description] VARCHAR(250) COLLATE SQL_Latin1_General_CP1_CI_AS NULL	, [KeyJson] VARCHAR(250) COLLATE SQL_Latin1_General_CP1_CI_AS NULL	, [Parent] SMALLINT NULL	, [Type] SMALLINT NULL DEFAULT((1))	, [OrderGrl] SMALLINT NULL DEFAULT((1))	, [Release] VARCHAR(MAX) COLLATE SQL_Latin1_General_CP1_CI_AS NULL DEFAULT('')	, [Active] BIT NULL	, CONSTRAINT [PK_ccPermisos] PRIMARY KEY ([Permissions_Id] ASC))